bool do_command(struct connection *c, struct spd_route *sr, const char *verb, /* <=== do_command */ 
		struct state *st)
{
	const char *verb_suffix;

	/* figure out which verb suffix applies for logging purposes */
	{
		const char *hs, *cs;

		switch (addrtypeof(&sr->this.host_addr)) {
		case AF_INET:
			hs = "-host";
			cs = "-client";
			break;
		case AF_INET6:
			hs = "-host-v6";
			cs = "-client-v6";
			break;
		default:
			loglog(RC_LOG_SERIOUS, "unknown address family");
			return FALSE;
		}
		verb_suffix = subnetisaddr(&sr->this.client,
					   &sr->this.host_addr) ?
			      hs : cs;
	}

	DBG(DBG_CONTROL, DBG_log("command executing %s%s",
				 verb, verb_suffix));

	if (kernel_ops->docommand != NULL) {
		return (*kernel_ops->docommand)(c, sr, verb, st);
	} else {
		DBG(DBG_CONTROL, DBG_log("no do_command for method %s",
					 kernel_ops->kern_name));
	}
	return TRUE;
}

void unroute_connection(struct connection *c) /* <=== unroute_connection */ 
{
	struct spd_route *sr;
	enum routing_t cr;

	for (sr = &c->spd; sr; sr = sr->next) {
		cr = sr->routing;

		if (erouted(cr)) {
			/* cannot handle a live one */
			passert(sr->routing != RT_ROUTED_TUNNEL);
			if (kernel_ops->shunt_eroute) {
				kernel_ops->shunt_eroute(c, sr, RT_UNROUTED,
							 ERO_DELETE, "delete");
			} else {   loglog(RC_COMMENT,
					  "no shunt_eroute implemented for %s interface",
					  kernel_ops->kern_name);
			}
#ifdef IPSEC_CONNECTION_LIMIT
			num_ipsec_eroute--;
#endif
		}

		sr->routing = RT_UNROUTED; /* do now so route_owner won't find us */

		/* only unroute if no other connection shares it */
		if (routed(cr) && route_owner(c, sr, NULL, NULL, NULL) == NULL)
			(void) do_command(c, sr, "unroute", NULL);
	}
}

#define clonereplacechunk(ch, addr, size, name) \ /* <=== include/lswalloc.h:66:68:clonereplacechunk:4 */ 
	do { pfreeany((ch).ptr); clonetochunk(ch, addr, size, name); \
	} while (0)

void delete_ipsec_sa(struct state *st USED_BY_KLIPS, /* <=== delete_ipsec_sa */ 
		     bool inbound_only USED_BY_KLIPS)
{
	switch (kern_interface) {
	case USE_MASTKLIPS:
	case USE_KLIPS:
	case USE_NETKEY:
		if (!inbound_only) {
			/* If the state is the eroute owner, we must adjust
			 * the routing for the connection.
			 */
			struct connection *c = st->st_connection;
			struct spd_route *sr;

			passert(st->st_connection);

			for (sr = &c->spd; sr; sr = sr->next) {
				if (sr->eroute_owner == st->st_serialno &&
				    sr->routing == RT_ROUTED_TUNNEL) {
					sr->eroute_owner = SOS_NOBODY;

					/* Routing should become RT_ROUTED_FAILURE,
					 * but if POLICY_FAIL_NONE, then we just go
					 * right back to RT_ROUTED_PROSPECTIVE as if no
					 * failure happened.
					 */
					sr->routing =
						(c->policy &
						 POLICY_FAIL_MASK) ==
						POLICY_FAIL_NONE ?
						RT_ROUTED_PROSPECTIVE :
						RT_ROUTED_FAILURE;

					if (sr == &c->spd &&
					    c->remotepeertype == CISCO)
						continue;

					(void) do_command(c, sr, "down", st);
					if ((c->policy & POLICY_DONT_REKEY) &&
					    c->kind == CK_INSTANCE) {
						/* in this special case, even if the connection
						 * is still alive (due to an ISAKMP SA),
						 * we get rid of routing.
						 * Even though there is still an eroute, the c->routing
						 * setting will convince unroute_connection to delete it.
						 * unroute_connection would be upset if c->routing == RT_ROUTED_TUNNEL
						 */
						unroute_connection(c);
					} else {
						(void) shunt_eroute(c, sr,
								    sr->routing, ERO_REPLACE,
								    "replace with shunt");
					}

#ifdef KLIPS_MAST
					/* in mast mode we must also delete the iptables rule */
					if (kern_interface == USE_MASTKLIPS)
						(void) sag_eroute(st, sr,
								  ERO_DELETE,
								  "delete");
#endif
				}
			}
#ifdef HAVE_LABELED_IPSEC
			if (!st->st_connection->loopback) {
#endif
			(void) teardown_half_ipsec_sa(st, FALSE);
#ifdef HAVE_LABELED_IPSEC
		}
#endif
		}
#ifdef HAVE_LABELED_IPSEC
		if (!st->st_connection->loopback || st->st_state ==
		    STATE_QUICK_I2) {
#endif
		(void) teardown_half_ipsec_sa(st, TRUE);
#ifdef HAVE_LABELED_IPSEC
	}
#endif

		break;
#if defined(WIN32) && defined(WIN32_NATIVE)
	case USE_WIN32_NATIVE:
		DBG(DBG_CONTROL,
		    DBG_log(
			    "No support (required?) to delete_ipsec_sa with Win2k"));
		break;
#endif
	case NO_KERNEL:
		DBG(DBG_CONTROL,
		    DBG_log(
			    "No support required to delete_ipsec_sa with NoKernel support"));
		break;
	default:
		DBG(DBG_CONTROL,
		    DBG_log("Unknown kernel stack in delete_ipsec_sa"));
		break;
	} /* switch kern_interface */
}

notification_t accept_KE(chunk_t *dest, const char *val_name, /* <=== accept_KE */ 
			 const struct oakley_group_desc *gr,
			 pb_stream *pbs)
{
	/* To figure out which function calls us without a pbs */
	passert(pbs != NULL);

	if (pbs_left(pbs) != gr->bytes) {
		loglog(RC_LOG_SERIOUS,
		       "KE has %u byte DH public value; %u required",
		       (unsigned) pbs_left(pbs), (unsigned) gr->bytes);
		/* XXX Could send notification back */
		return INVALID_KEY_INFORMATION;
	}
	clonereplacechunk(*dest, pbs->cur, pbs_left(pbs), val_name);
	DBG_cond_dump_chunk(DBG_CRYPT, "DH public value received:\n", *dest);
	return NOTHING_WRONG;
}

const char *enum_name(enum_names *ed, unsigned long val) /* <=== enum_name */ 
{
	enum_names  *p;

	for (p = ed; p != NULL; p = p->en_next_range)
		if (p->en_first <= val && val <= p->en_last)
			return p->en_names[val - p->en_first];

	return NULL;
}

static char *humanize_number(unsigned long num, /* <=== humanize_number */ 
			     char *buf,
			     char *buf_roof,
			     const char *prefix)
{
	size_t buf_len = buf_roof - buf;
	unsigned long to_print = num;
	const char *suffix;
	int ret;
	bool kilos = prefix[0] == '!';

	if (!kilos && num < 1024) {
		suffix = "B";
	} else {
		if (!kilos)
			to_print /= 1024;

		if (to_print < 1024) {
			suffix = "KB";
		} else {
			to_print /= 1024;
			suffix = "MB";
		}
	}

	ret = snprintf(buf, buf_len, "%s%lu%s", prefix, to_print,
		       suffix + kilos);
	if (ret < 0 || (size_t) ret >= buf_len)
		return buf;

	return buf + ret;
}

static void pluto_do_crypto_op(struct pluto_crypto_req *r, int helpernum) /* <=== pluto_do_crypto_op */ 
{
	DBG(DBG_CONTROL,
	    DBG_log("helper %d doing %s op id: %u",
		    helpernum,
		    enum_show(&pluto_cryptoop_names, r->pcr_type),
		    r->pcr_id));
#ifdef DEBUG
	{
		char *d = getenv("PLUTO_CRYPTO_HELPER_DELAY");
		if (d != NULL) {
			int delay = atoi(d);

			DBG_log("helper is pausing for %d seconds", delay);
			sleep(delay);
		}
	}
#endif

	/* now we have the entire request in the buffer, process it */
	switch (r->pcr_type) {
	case pcr_build_kenonce:
		calc_ke(r);
		calc_nonce(r);
		break;

	case pcr_build_nonce:
		calc_nonce(r);
		break;

	case pcr_compute_dh_iv:
		calc_dh_iv(r);
		break;

	case pcr_compute_dh:
		calc_dh(r);
		break;

	case pcr_compute_dh_v2:
		calc_dh_v2(r);
		break;

	case pcr_rsa_sign:
	case pcr_rsa_check:
	case pcr_x509cert_fetch:
	case pcr_x509crl_fetch:
		break;
	}
}

struct state *new_state(void) /* <=== new_state */ 
{
	static const struct state blank_state;  /* initialized all to zero & NULL */
	static so_serial_t next_so = SOS_FIRST;
	struct state *st;

	st = clone_thing(blank_state, "struct state in new_state()");
	st->st_serialno = next_so++;
	passert(next_so > SOS_FIRST);   /* overflow can't happen! */
	st->st_whack_sock = NULL_FD;

	anyaddr(AF_INET, &st->hidden_variables.st_nat_oa);
	anyaddr(AF_INET, &st->hidden_variables.st_natd);

	DBG(DBG_CONTROL, DBG_log("creating state object #%lu at %p",
				 st->st_serialno, (void *) st));
	return st;
}

stf_status build_ke(struct pluto_crypto_req_cont *cn, /* <=== build_ke */ 
		    struct state *st,
		    const struct oakley_group_desc *group,
		    enum crypto_importance importance)
{
	continuation = cn;
	memset(&rd, 0, sizeof(rd));

	r->pcr_len  = sizeof(struct pluto_crypto_req);
	r->pcr_type = pcr_build_kenonce;
	r->pcr_pcim = importance;

	pcr_init(r, pcr_build_kenonce, importance);
	r->pcr_d.kn.oakley_group   = group->group;

	return STF_SUSPEND;
}

bool out_zero(size_t len, pb_stream *outs, const char *name) /* <=== out_zero */ 
{
	if (pbs_left(outs) < len) {
		loglog(RC_LOG_SERIOUS,
		       "not enough room left to place %s in %s", name,
		       outs->name);
		return FALSE;
	} else {
		DBG(DBG_EMITTING,
		    DBG_log("emitting %u zero bytes of %s into %s",
			    (unsigned) len, name, outs->name));
		memset(outs->cur, 0x00, len);
		outs->cur += len;
		return TRUE;
	}
}

v2_notification_t accept_v2_nonce(struct msg_digest *md, chunk_t *dest, /* <=== accept_v2_nonce */ 
				  const char *name)
{
	pb_stream *nonce_pbs = &md->chain[ISAKMP_NEXT_v2Ni]->pbs;
	size_t len = pbs_left(nonce_pbs);

	if (len < MINIMUM_NONCE_SIZE || MAXIMUM_NONCE_SIZE < len) {
		loglog(RC_LOG_SERIOUS, "%s length not between %d and %d",
			name, MINIMUM_NONCE_SIZE, MAXIMUM_NONCE_SIZE);
		return v2N_INVALID_SYNTAX; /* ??? */
	}
	clonereplacechunk(*dest, nonce_pbs->cur, len, "nonce");
	return NOTHING_WRONG;
}

void connection_discard(struct connection *c) /* <=== connection_discard */ 
{
	if (c->kind == CK_INSTANCE) {
		if (in_pending_use(c))
			return;

		if (!states_use_connection(c))
			delete_connection(c, FALSE);
	}
}

struct pending **host_pair_first_pending(const struct connection *c) /* <=== host_pair_first_pending */ 
{
	if (c->host_pair == NULL)
		return NULL;

	return &c->host_pair->pending;
}

void libreswan_loglog(int mess_no UNUSED, const char *message, ...) /* <=== libreswan_loglog */ 
{
	va_list args;
	char m[LOG_WIDTH]; /* longer messages will be truncated */

	va_start(args, message);
	fmt_log(m, sizeof(m), message, args);
	va_end(args);

	if (log_to_stderr)
		fprintf(stderr, "%s\n", m);
	if (log_to_syslog)
		syslog(LOG_WARNING, "%s", m);
}

static size_t                   /* size of text, including NUL */ /* <=== normal6 */ 
normal6(srcp, srclen, buf, dstp, squish)
const unsigned char *srcp;
size_t srclen;
char *buf;                      /* guaranteed large enough, plus 2 */
char **dstp;                    /* where to put result pointer */
int squish;                     /* whether to squish out 0:0 */
{
	int i;
	unsigned long piece;
	char *p;
	char *q;

	if (srclen != IP6BYTES) /* "can't happen" */
		return 0;

	p = buf;
	*p++ = ':';
	for (i = 0; i < IP6BYTES / 2; i++) {
		piece = (srcp[2 * i] << 8) + srcp[2 * i + 1];
		p += ultot(piece, 16, p, 5);    /* 5 = abcd + NUL */
		*(p - 1) = ':';                 /* overwrites the NUL */
	}
	*p = '\0';
	q = strstr(buf, ":0:0:");
	if (squish && q != NULL) {      /* zero squishing is possible */
		p = q + 1;
		while (*p == '0' && *(p + 1) == ':')
			p += 2;
		q++;
		*q++ = ':';     /* overwrite first 0 */
		while (*p != '\0')
			*q++ = *p++;
		*q = '\0';
		if (!(*(q - 1) == ':' && *(q - 2) == ':'))
			*--q = '\0';    /* strip final : unless :: */
		p = buf;
		if (!(*p == ':' && *(p + 1) == ':'))
			p++;    /* skip initial : unless :: */
	} else {
		q = p;
		*--q = '\0';    /* strip final : */
		p = buf + 1;    /* skip initial : */
	}
	*dstp = p;
	return q - p + 1;
}

bool in_pending_use(struct connection *c) /* <=== in_pending_use */ 
{
	/* see if it is being used by a pending */
	struct pending **pp, *p;

	pp = host_pair_first_pending(c);
	if (pp == NULL)
		return FALSE;

	for (p = *pp; p != NULL; p = p->next)
		if (p->connection == c)
			return TRUE; /* in use, so we're done */

	return FALSE;
}

void _delete_dpd_event(struct state *st, const char *file, int lineno) /* <=== _delete_dpd_event */ 
{
	DBG(DBG_DPD | DBG_CONTROL,
	    DBG_log("state: %ld requesting DPD event %s to be deleted by %s:%d",
		    st->st_serialno,
		    (st->st_dpd_event != NULL ?
		     enum_show(&timer_event_names, st->st_dpd_event->ev_type) :
		     "none"),
		    file, lineno));

	if (st->st_dpd_event != (struct event *) NULL) {
		struct event **ev;

		for (ev = &evlist;; ev = &(*ev)->ev_next) {
			if (*ev == NULL) {
				DBG(DBG_DPD | DBG_CONTROL,
				    DBG_log(
					    "DPD event %s to be deleted not found",
					    enum_show(&timer_event_names,
						      st->st_dpd_event->ev_type)));
				break;
			}
			if ((*ev) == st->st_dpd_event) {
				*ev = (*ev)->ev_next;
				pfree(st->st_dpd_event);
				st->st_dpd_event = (struct event *) NULL;
				break;
			}
		}
	}
}

void delete_connection(struct connection *c, bool relations) /* <=== delete_connection */ 
{
	struct spd_route *sr;
	struct connection *old_cur_connection =
		cur_connection == c ? NULL : cur_connection;

#ifdef DEBUG
	lset_t old_cur_debugging = cur_debugging;
#endif
	union {
		struct alg_info** ppai;
		struct alg_info_esp** ppai_esp;
		struct alg_info_ike** ppai_ike;
	} palg_info;

	set_cur_connection(c);

	/*
	 * Must be careful to avoid circularity:
	 * we mark c as going away so it won't get deleted recursively.
	 */
	passert(c->kind != CK_GOING_AWAY);
	if (c->kind == CK_INSTANCE) {
		libreswan_log(
			"deleting connection \"%s\" instance with peer %s "
			"{isakmp=#%lu/ipsec=#%lu}",
			c->name,
			ip_str(&c->spd.that.host_addr),
			c->newest_isakmp_sa, c->newest_ipsec_sa);
		c->kind = CK_GOING_AWAY;
		rel_lease_addr(c);
	} else {
		libreswan_log("deleting connection");
	}
	release_connection(c, relations); /* won't delete c */

	if (c->kind == CK_GROUP)
		delete_group(c);

#if 0
	/* TODO:  this will be enabled in the next version */
	if ((c->pool != NULL) && (c->kind == CK_TEMPLATE)) {
		DBG(DBG_CONTROLMORE,
			DBG_log("free addresspool entry for the conn %s "
				"kind %s conn serial %d pool refcnt %u",
				c->name, enum_name(&connection_kind_names,
						c->kind),
				c->instance_serial,
				c->pool->refcnt));
		free_addresspool_entry(c->pool);
		*&c->pool = NULL;
	}
#endif

	/* free up any logging resources */
	perpeer_logfree(c);

	/* find and delete c from connections list */
	list_rm(struct connection, ac_next, c, connections);
	cur_connection = old_cur_connection;

	/* find and delete c from the host pair list */
	if (c->host_pair == NULL) {
		list_rm(struct connection, hp_next, c, unoriented_connections);
	} else {
		struct host_pair *hp = c->host_pair;

		list_rm(struct connection, hp_next, c, hp->connections);
		c->host_pair = NULL; /* redundant, but safe */

		/*
		 * if there are no more connections with this host_pair
		 * and we haven't even made an initial contact, let's delete
		 * this guy in case we were created by an attempted DOS attack.
		 */
		if (hp->connections == NULL) {
			/* ??? must deal with this! */
			passert(hp->pending == NULL);
			remove_host_pair(hp);
			pfree(hp);
		}
	}

	if (c->kind != CK_GOING_AWAY)
		pfreeany(c->spd.that.virt);

#ifdef DEBUG
	set_debugging(old_cur_debugging);
#endif
	pfreeany(c->name);
	pfreeany(c->cisco_dns_info);
	pfreeany(c->modecfg_domain);
	pfreeany(c->modecfg_banner);
#ifdef HAVE_LABELED_IPSEC
	pfreeany(c->policy_label);
#endif
	pfreeany(c->dnshostname);

	sr = &c->spd;
	while (sr) {
		delete_sr(sr);
		sr = sr->next;
	}

	free_generalNames(c->requested_ca, TRUE);

	gw_delref(&c->gw_info);
	palg_info.ppai_esp = &c->alg_info_esp;
	alg_info_delref(palg_info.ppai);
	palg_info.ppai_ike = &c->alg_info_ike;
	alg_info_delref(palg_info.ppai);
	pfree(c);
}

bool out_raw(const void *bytes, size_t len, pb_stream *outs, const char *name) /* <=== out_raw */ 
{
	if (pbs_left(outs) < len) {
		loglog(RC_LOG_SERIOUS,
		       "not enough room left to place %lu bytes of %s in %s",
		       (unsigned long) len, name, outs->name);
		return FALSE;
	} else {
		DBG(DBG_EMITTING,
		    DBG_log("emitting %u raw bytes of %s into %s",
			    (unsigned) len, name, outs->name);
		    DBG_dump(name, bytes, len));
		memcpy(outs->cur, bytes, len);
		outs->cur += len;
		return TRUE;
	}
}

static void fmt_log(char *buf, size_t buf_len, /* <=== fmt_log */ 
		    const char *fmt, va_list ap)
{
	bool reproc = *fmt == '~';
	size_t ps;

	buf[0] = '\0';
	if (reproc) {
		fmt++; /* ~ at start of format suppresses this prefix */
	} else if (progname != NULL && (strlen(progname) + 1 + 1) < buf_len) {
		/* start with name of connection */
		strncat(buf, progname, buf_len - 1);
		strncat(buf, " ", buf_len - 1);
	}

	ps = strlen(buf);
	vsnprintf(buf + ps, buf_len - ps, fmt, ap);
	if (!reproc)
		(void)sanitize_string(buf, buf_len);
}

static bool shunt_eroute(struct connection *c, /* <=== shunt_eroute */ 
			 struct spd_route *sr,
			 enum routing_t rt_kind,
			 enum pluto_sadb_operations op,
			 const char *opname)
{
	if (kernel_ops->shunt_eroute)
		return kernel_ops->shunt_eroute(c, sr, rt_kind, op, opname);

	loglog(RC_COMMENT, "no shunt_eroute implemented for %s interface",
	       kernel_ops->kern_name);
	return TRUE;
}

err_t send_crypto_helper_request(struct pluto_crypto_req *r, /* <=== send_crypto_helper_request */ 
				 struct pluto_crypto_req_cont *cn,
				 bool *toomuch)
{
	struct pluto_crypto_worker *w;
	int cnt;

	/* do it all ourselves? */
	if (pc_workers == NULL) {
		reset_cur_state();

		pluto_do_crypto_op(r, pc_helper_num);
		/* call the continuation */
		(*cn->pcrc_func)(cn, r, NULL);

		/* indicate that we did everything ourselves */
		*toomuch = TRUE;

		pfree(cn);
		return NULL;
	}

	/* set up the id */
	r->pcr_id = pcw_id++;
	cn->pcrc_id = r->pcr_id;
	cn->pcrc_pcr = r;

	/* find an available worker */
	cnt = pc_workers_cnt;
	do {
		pc_worker_num++;
		if (pc_worker_num >= pc_workers_cnt)
			pc_worker_num = 0;
		w = &pc_workers[pc_worker_num];

		DBG(DBG_CONTROL,
		    DBG_log("%d: w->pcw_dead: %d w->pcw_work: %d cnt: %d",
			    pc_worker_num, w->pcw_dead, w->pcw_work, cnt));

		/* see if there is something to clean up after */
		if (w->pcw_dead      == TRUE &&
		    w->pcw_reaped == TRUE) {
			cleanup_crypto_helper(w, 0);
			DBG(DBG_CONTROL,
			    DBG_log(
				    "clnup %d: w->pcw_dead: %d w->pcw_work: %d cnt: %d",
				    pc_worker_num, w->pcw_dead, w->pcw_work,
				    cnt));
		}
	} while (((w->pcw_work >= w->pcw_maxbasicwork)) &&
		 --cnt > 0);

	if (cnt == 0 && r->pcr_pcim > pcim_ongoing_crypto) {
		cnt = pc_workers_cnt;
		while ((w->pcw_work >= w->pcw_maxcritwork) &&
		       --cnt > 0) {

			/* find an available worker */
			pc_worker_num++;
			if (pc_worker_num >= pc_workers_cnt)
				pc_worker_num = 0;

			w = &pc_workers[pc_worker_num];
			/* see if there is something to clean up after */
			if (w->pcw_dead      == TRUE &&
			    w->pcw_reaped == TRUE)
				cleanup_crypto_helper(w, 0);
		}
		DBG(DBG_CONTROL,
		    DBG_log("crit %d: w->pcw_dead: %d w->pcw_work: %d cnt: %d",
			    pc_worker_num, w->pcw_dead, w->pcw_work, cnt));
	}

	if (cnt == 0 && r->pcr_pcim >= pcim_demand_crypto) {
		/* it is very important. Put it all on a queue for later */

		TAILQ_INSERT_TAIL(&backlog, cn, pcrc_list);

		/* copy the request */
		r = clone_bytes(r, r->pcr_len, "saved cryptorequest");
		cn->pcrc_pcr = r;

		cn->pcrc_reply_stream = reply_stream;
		if (pbs_offset(&reply_stream)) {
			cn->pcrc_reply_buffer = clone_bytes(reply_stream.start,
							    pbs_offset(&
								       reply_stream),
							    "saved reply buffer");
		}

		backlogqueue_len++;
		DBG(DBG_CONTROL,
		    DBG_log(
			    "critical demand crypto operation queued on backlog as %d'th item, id: q#%u",
			    backlogqueue_len, r->pcr_id));
		*toomuch = FALSE;
		return NULL;
	}

	if (cnt == 0) {
		/* didn't find any workers */
		DBG(DBG_CONTROL,
		    DBG_log("failed to find any available worker (import=%s)",
			    enum_name(&pluto_cryptoimportance_names,
				      r->pcr_pcim)));

		*toomuch = TRUE;
		return "failed to find any available worker";
	}

	/* w points to a work. Make sure it is live */
	if (w->pcw_pid == -1) {
		init_crypto_helper(w, pc_worker_num);
		if (w->pcw_pid == -1) {
			DBG(DBG_CONTROL,
			    DBG_log(
				    "found only a dead helper, and failed to restart it"));
			*toomuch = TRUE;
			return "failed to start a new helper";
		}
	}

	/* link it to the active worker list */
	TAILQ_INSERT_TAIL(&w->pcw_active, cn, pcrc_list);

	passert(w->pcw_pid != -1);
	passert(w->pcw_pipe != -1);
	passert(w->pcw_work < w->pcw_maxcritwork);

	cn->pcrc_reply_stream = reply_stream;
	if (pbs_offset(&reply_stream)) {
		cn->pcrc_reply_buffer = clone_bytes(reply_stream.start,
						    pbs_offset(
							    &reply_stream),
						    "saved reply buffer");
	}

	if (!crypto_write_request(w, r)) {
		libreswan_log("failed to write crypto request: %s\n",
			      strerror(errno));
		if (pbs_offset(&cn->pcrc_reply_stream))
			pfree(cn->pcrc_reply_buffer);
		cn->pcrc_reply_buffer = NULL;
		return "failed to write";
	}

	w->pcw_work++;
	*toomuch = FALSE;
	return NULL;
}

void flush_pending_by_state(struct state *st) /* <=== flush_pending_by_state */ 
{
	struct pending **pp,
	*p;

	pp = host_pair_first_pending(st->st_connection);
	if (pp == NULL)
		return;

	while ((p = *pp) != NULL) {
		if (p->isakmp_sa == st) {
			/* we don't have to worry about deref to free'ed
			 * *pp, because delete_pending updates pp to
			 * point to the next element before it frees *pp
			 */
			delete_pending(pp);
		} else {
			pp = &p->next;
		}
	}
}

const char *enum_show(enum_names *ed, unsigned long val) /* <=== enum_show */ 
{
	const char *p = enum_name(ed, val);

	if (p == NULL) {
		static char buf[12]; /* only one!  I hope that it is big enough */

		snprintf(buf, sizeof(buf), "%lu??", val);
		p = buf;
	}
	return p;
}

static void delete_pending(struct pending **pp) /* <=== delete_pending */ 
{
	struct pending *p = *pp;

	*pp = p->next;
	if (p->connection != NULL)
		connection_discard(p->connection);
	close_any(p->whack_sock);

	DBG(DBG_DPD,
	    DBG_log("removing pending policy for \"%s\" {%p}",
		    p->connection ? p->connection->name : "none", p));

#ifdef HAVE_LABELED_IPSEC
	pfreeany(p->uctx);
#endif

	pfree(p);
}

