void release_fragments(struct state *st) /* <=== release_fragments */ 
{
	struct ike_frag *frag;

	if (!st)
		return;

	frag = st->ike_frags;
	while (frag) {
		struct ike_frag *this = frag;
		frag = this->next;
		release_md(this->md);
		free(this);
	}

	st->ike_frags = NULL;
}

static bool crypto_write_request(struct pluto_crypto_worker *w, /* <=== crypto_write_request */ 
				 struct pluto_crypto_req *r)
{
	unsigned char *wdat = (unsigned char *)r;
	int wlen = r->pcr_len;
	int cnt;

	DBG(DBG_CONTROL,
	    DBG_log(
		    "asking helper %d to do %s op on seq: %u (len=%u, pcw_work=%d)",
		    w->pcw_helpernum,
		    enum_show(&pluto_cryptoop_names, r->pcr_type),
		    r->pcr_id, (unsigned int)r->pcr_len, w->pcw_work + 1));

	do {
		errno = 0;
		cnt = write(w->pcw_pipe, wdat, wlen);

		if (cnt <= 0) {
			libreswan_log(
				"write to helper failed: cnt=%d err=%s\n",
				cnt, strerror(errno));
			return FALSE;
		}
		if (DBGP(DBG_CONTROL) || cnt != wlen) {
			DBG_log(
				"crypto helper write of request: cnt=%d<wlen=%d. \n", cnt,
				wlen);
		}

		wlen -= cnt;
		wdat += cnt;

	} while (wlen > 0);

	return TRUE;
}

static void fmt_log(char *buf, size_t buf_len, const char *fmt, va_list ap) /* <=== fmt_log */ 
{
	bool reproc = *fmt == '~';
	size_t ps;
	struct connection *c = cur_state != NULL ? cur_state->st_connection :
			       cur_connection;

	buf[0] = '\0';
	if (reproc) {
		fmt++; /* ~ at start of format suppresses this prefix */
	} else if (c != NULL) {
		/* start with name of connection */
		char *const be = buf + buf_len;
		char *bp = buf;

		snprintf(bp, be - bp, "\"%s\"", c->name);
		bp += strlen(bp);

		/* if it fits, put in any connection instance information */
		if (be - bp > CONN_INST_BUF) {
			fmt_conn_instance(c, bp);
			bp += strlen(bp);
		}

		if (cur_state != NULL) {
			/* state number */
			snprintf(bp, be - bp, " #%lu", cur_state->st_serialno);
			bp += strlen(bp);
		}
		snprintf(bp, be - bp, ": ");
	} else if (cur_from != NULL) {
		/* peer's IP address */
		/* Note: must not use ip_str() because our caller might! */
		char ab[ADDRTOT_BUF];

		(void) addrtot(cur_from, 0, ab, sizeof(ab));
		snprintf(buf, buf_len, "packet from %s:%u: ",
			 ab, (unsigned)cur_from_port);
	}

	ps = strlen(buf);
	vsnprintf(buf + ps, buf_len - ps, fmt, ap);
	if (!reproc)
		(void)sanitize_string(buf, buf_len);
}

static inline void pcr_init(struct pluto_crypto_req *r, /* <=== pcr_init */ 
			    enum pluto_crypto_requests pcr_type,
			    enum crypto_importance pcr_pcim)
{
	memset(r, 0, sizeof(*r));
	r->pcr_len  = sizeof(struct pluto_crypto_req);
	r->pcr_type = pcr_type;
	r->pcr_pcim = pcr_pcim;

	switch (r->pcr_type) {
	case pcr_build_kenonce:
	case pcr_build_nonce:
		r->pcr_d.kn.thespace.start = 0;
		r->pcr_d.kn.thespace.len   = sizeof(r->pcr_d.kn.space);
		break;
	case pcr_compute_dh_iv:
	case pcr_compute_dh:
	case pcr_compute_dh_v2:
		r->pcr_d.dhq.thespace.start = 0;
		r->pcr_d.dhq.thespace.len   = sizeof(r->pcr_d.dhq.space);
		break;
	case pcr_rsa_sign:
	case pcr_rsa_check:
	case pcr_x509cert_fetch:
	case pcr_x509crl_fetch:
		passert(0);
		break;
	}
}

stf_status build_ke(struct pluto_crypto_req_cont *cn, /* <=== build_ke */ 
		    struct state *st,
		    const struct oakley_group_desc *group,
		    enum crypto_importance importance)
{
	struct pluto_crypto_req rd;
	struct pluto_crypto_req *r = &rd;
	err_t e;
	bool toomuch = FALSE;

	pcr_init(r, pcr_build_kenonce, importance);
	r->pcr_d.kn.oakley_group   = group->group;

	cn->pcrc_serialno = st->st_serialno;
	e = send_crypto_helper_request(r, cn, &toomuch);

	if (e != NULL) {
		loglog(RC_LOG_SERIOUS, "can not start crypto helper: %s", e);
		if (toomuch)
			return STF_TOOMUCHCRYPTO;
		else
			return STF_FAIL;
	} else if (!toomuch) {
		st->st_calculating = TRUE;
		delete_event(st);
		event_schedule(EVENT_CRYPTO_FAILED, EVENT_CRYPTO_FAILED_DELAY,
			       st);
		return STF_SUSPEND;
	} else {
		/* we must have run the continuation directly, so
		 * complete_v1_state_transition already got called.
		 */
		return STF_INLINE;
	}
}

void whack_log(int mess_no, const char *message, ...) /* <=== whack_log */ 
{
	int wfd;

	pthread_mutex_lock(&log_mutex);
	wfd = whack_log_fd != NULL_FD ? whack_log_fd :
	      cur_state != NULL ? cur_state->st_whack_sock :
	      NULL_FD;

	if (wfd != NULL_FD
#ifdef DEBUG
	    || dying_breath
#endif
	    ) {
		va_list args;
		char m[LOG_WIDTH]; /* longer messages will be truncated */
		int prelen = snprintf(m, sizeof(m), "%03d ", mess_no);

		passert(prelen >= 0);

		va_start(args, message);
		fmt_log(m + prelen, sizeof(m) - prelen, message, args);
		va_end(args);

#if DEBUG
		if (dying_breath) {
			/* status output copied to log */
			if (log_to_stderr || (log_to_file && pluto_log_fd))
				fprintf(log_to_stderr ? stderr : pluto_log_fd,
					"%s\n", m + prelen);
			if (log_to_syslog)
				syslog(LOG_WARNING, "%s", m + prelen);
			if (log_to_perpeer)
				peerlog("", m);
		}
#endif

		if (wfd != NULL_FD) {
			/* write to whack socket, but suppress possible SIGPIPE */
			size_t len = strlen(m);
#ifdef MSG_NOSIGNAL                     /* depends on version of glibc??? */
			m[len] = '\n';  /* don't need NUL, do need NL */
			(void) send(wfd, m, len + 1, MSG_NOSIGNAL);
#else /* !MSG_NOSIGNAL */
			int r;
			struct sigaction act,
					 oldact;

			m[len] = '\n'; /* don't need NUL, do need NL */
			act.sa_handler = SIG_IGN;
			sigemptyset(&act.sa_mask);
			act.sa_flags = 0; /* no nothing */
			r = sigaction(SIGPIPE, &act, &oldact);
			passert(r == 0);

			(void) write(wfd, m, len + 1);

			r = sigaction(SIGPIPE, &oldact, NULL);
			passert(r == 0);
#endif                  /* !MSG_NOSIGNAL */
		}
	}
	pthread_mutex_unlock(&log_mutex);
}

bool testset(const char *const table[], lset_t val) /* <=== testset */ 
{
	lset_t bit;
	const char *const *tp;

	for (tp = table, bit = 01; val != 0; bit <<= 1, tp++) {
		const char *n = *tp;

		if (n == NULL || ((val & bit) && *n == '\0'))
			return FALSE;

		val &= ~bit;
	}
	return TRUE;
}

static void cleanup_crypto_helper(struct pluto_crypto_worker *w, /* <=== cleanup_crypto_helper */ 
				  int status)
{
	if (w->pcw_pipe) {
		loglog(RC_LOG_SERIOUS,
		       "closing helper(%u) pid=%lu fd=%d exit=%d",
		       w->pcw_helpernum, w->pcw_pid, w->pcw_pipe, status);
		close(w->pcw_pipe);
	}

	w->pcw_pid = -1;
	w->pcw_work = 0;        /* ?!? */
	w->pcw_reaped = FALSE;
	w->pcw_dead   = FALSE;  /* marking is not dead lets it live again */
}

size_t                          /* space needed for full conversion */ /* <=== addrtot */ 
addrtot(src, format, dst, dstlen)
const ip_address * src;
int format;                     /* character */
char *dst;                      /* need not be valid if dstlen is 0 */
size_t dstlen;
{
	unsigned char *b;
	size_t n;
	char buf[1 + ADDRTOT_BUF + 1];      /* :address: */
	char *p;
	int t = addrtypeof(src);
#       define  TF(t, f)        (((t) << 8) | (f))

	n = addrbytesptr(src, &b);
	if (n == 0) {
		dst[0] = '\0';
		strncat(dst, "<invalid>", dstlen - 1); /* we hope possible truncation does not cause problems */
		return sizeof("<invalid>");
	}

	switch (TF(t, format)) {
	case TF(AF_INET, 0):
		n = normal4(b, n, buf, &p);
		break;
	case TF(AF_INET6, 0):
		n = normal6(b, n, buf, &p, 1);
		break;
	case TF(AF_INET, 'Q'):
		n = normal4(b, n, buf, &p);
		break;
	case TF(AF_INET6, 'Q'):
		n = normal6(b, n, buf, &p, 0);
		break;
	case TF(AF_INET, 'r'):
		n = reverse4(b, n, buf, &p);
		break;
	case TF(AF_INET6, 'r'):
		n = reverse6(b, n, buf, &p);
		break;
	default:                                        /* including (AF_INET, 'R') */
		dst[0] = '\0';
		strncat(dst, "<invalid>", dstlen - 1);  /* we hope possible truncation does not cause problems */
		return sizeof("<invalid>");
	}

	if (dstlen > 0) {
		if (dstlen < n)
			p[dstlen - 1] = '\0';
		strcpy(dst, p);
	}
	return n;
}

static size_t                   /* size of text, including NUL */ /* <=== reverse6 */ 
reverse6(srcp, srclen, buf, dstp)
const unsigned char *srcp;
size_t srclen;
char *buf;                      /* guaranteed large enough */
char **dstp;                    /* where to put result pointer */
{
	int i;
	unsigned long piece;
	char *p;

	if (srclen != IP6BYTES) /* "can't happen" */
		return 0;

	p = buf;
	for (i = IP6BYTES - 1; i >= 0; i--) {
		piece = srcp[i];
		p += ultot(piece & 0xf, 16, p, 2);
		*(p - 1) = '.';
		p += ultot(piece >> 4, 16, p, 2);
		*(p - 1) = '.';
	}
	strcpy(p, "IP6.ARPA.");
	*dstp = buf;
	return strlen(buf) + 1;
}

void close_message(pb_stream *pbs, struct state *st) /* <=== close_message */ 
{
	size_t padding =  pad_up(pbs_offset(pbs), 4);

	/* Workaround for overzealous Checkpoint firewal */
	if (padding && st && st->st_connection &&
	    (st->st_connection->policy & POLICY_NO_IKEPAD)) {
		DBG(DBG_CONTROLMORE, DBG_log("IKE message padding of %lu bytes skipped by policy",
			padding));
		padding = 0;
	}

	if (padding != 0) {
		DBG(DBG_CONTROLMORE, DBG_log("padding IKE message with %lu bytes", padding));
		(void) out_zero(padding, pbs, "message padding");
	} else {
		DBG(DBG_CONTROLMORE, DBG_log("no IKE message padding required"));
	}

	close_output_pbs(pbs);
}

static int build_ike_version() /* <=== build_ike_version */ 
{
return ((IKEv2_MAJOR_VERSION + (DBGP(IMPAIR_MAJOR_VERSION_BUMP) ? 1 : 0))
	<< ISA_MAJ_SHIFT) | (IKEv2_MINOR_VERSION +
	(DBGP(IMPAIR_MINOR_VERSION_BUMP) ? 1 : 0));
}

