{
	unsigned int i;

	for (i = 0; i < pc->prop_cnt; i++)
		free_sa_prop(&pc->props[i]);
	if (pc->props)
		pfree(pc->props);
}

void delete_state(struct state *st) /* <=== delete_state */ 
{
	struct connection *const c = st->st_connection;
	struct state *old_cur_state = cur_state == st ? NULL : cur_state;

	DBG(DBG_CONTROL, DBG_log("deleting state #%lu", st->st_serialno));

	if (IS_IPSEC_SA_ESTABLISHED(st->st_state)) {
		/* Note that a state/SA can have more then one of ESP/AH/IPCOMP */
		if (st->st_esp.present) {
			char statebuf[1024], *sbcp;

			sbcp = humanize_number(st->st_esp.peer_bytes,
					       statebuf, statebuf +
					       sizeof(statebuf),
					       "ESP traffic information: in=");
			sbcp = humanize_number(st->st_esp.our_bytes,
					       sbcp,
					       statebuf + sizeof(statebuf),
					       " out=");
			if (st->st_xauth_username &&
			    st->st_xauth_username[0] != '\0')
				libreswan_log("%s XAUTHuser=%s", statebuf,
					      st->st_xauth_username);
			else
				libreswan_log("%s", statebuf);
		}

		if (st->st_ah.present) {
			char statebuf[1024], *sbcp;

			sbcp = humanize_number(st->st_ah.peer_bytes,
					       statebuf, statebuf +
					       sizeof(statebuf),
					       "AH traffic information: in=");
			sbcp = humanize_number(st->st_ah.our_bytes,
					       sbcp,
					       statebuf + sizeof(statebuf),
					       " out=");
			if (st->st_xauth_username &&
			    st->st_xauth_username[0] != '\0')
				libreswan_log("%s XAUTHuser=%s", statebuf,
					      st->st_xauth_username);
			else
				libreswan_log("%s", statebuf);
		}

		if (st->st_ipcomp.present) {
			char statebuf[1024], *sbcp;

			sbcp = humanize_number(st->st_ipcomp.peer_bytes,
					       statebuf, statebuf +
					       sizeof(statebuf),
					       " IPCOMP traffic information: in=");
			sbcp = humanize_number(st->st_ipcomp.our_bytes,
					       sbcp,
					       statebuf + sizeof(statebuf),
					       " out=");
			if (st->st_xauth_username &&
			    st->st_xauth_username[0] != '\0')
				libreswan_log("%s XAUTHuser=%s", statebuf,
					      st->st_xauth_username);
			else
				libreswan_log("%s", statebuf);
		}
	}

#ifdef XAUTH_HAVE_PAM
	state_deletion_xauth_cleanup(st);
#endif

	/* If DPD is enabled on this state object, clear any pending events */
	if (st->st_dpd_event != NULL)
		delete_dpd_event(st);

	/* if there is a suspended state transition, disconnect us */
	if (st->st_suspended_md != NULL) {
		passert(st->st_suspended_md->st == st);
		DBG(DBG_CONTROL, DBG_log("disconnecting state #%lu from md",
					 st->st_serialno));
		st->st_suspended_md->st = NULL;
	}

	/* tell the other side of any IPSEC SAs that are going down */
	if (IS_IPSEC_SA_ESTABLISHED(st->st_state) ||
	    IS_ISAKMP_SA_ESTABLISHED(st->st_state))
		send_delete(st);

	delete_event(st); /* delete any pending timer event */

	/* Ditch anything pending on ISAKMP SA being established.
	 * Note: this must be done before the unhash_state to prevent
	 * flush_pending_by_state inadvertently and prematurely
	 * deleting our connection.
	 */
	flush_pending_by_state(st);

	/* if there is anything in the cryptographic queue, then remove this
	 * state from it.
	 */
	delete_cryptographic_continuation(st);

	/* effectively, this deletes any ISAKMP SA that this state represents */
	unhash_state(st);

	/* tell kernel to delete any IPSEC SA
	 * ??? we ought to tell peer to delete IPSEC SAs
	 */
	if (IS_IPSEC_SA_ESTABLISHED(st->st_state) ||
	    IS_CHILD_SA_ESTABLISHED(st))
		delete_ipsec_sa(st, FALSE);
	else if (IS_ONLY_INBOUND_IPSEC_SA_ESTABLISHED(st->st_state))
		delete_ipsec_sa(st, TRUE);

	if (c->newest_ipsec_sa == st->st_serialno)
		c->newest_ipsec_sa = SOS_NOBODY;

	if (c->newest_isakmp_sa == st->st_serialno)
		c->newest_isakmp_sa = SOS_NOBODY;

	/*
	 * fake a state change here while we are still associated with a
	 * connection.  Without this the state logging (when enabled) cannot
	 * work out what happened.
	 */
	fake_state(st, STATE_UNDEFINED);

	st->st_connection = NULL;       /* we might be about to free it */
	cur_state = old_cur_state;      /* without st_connection, st isn't complete */
	connection_discard(c);

	change_state(st, STATE_UNDEFINED);

	release_whack(st);

	/* from here on we are just freeing RAM */

	{
		struct msgid_list *p = st->st_used_msgids;

		while (p != NULL) {
			struct msgid_list *q = p;
			p = p->next;
			pfree(q);
		}
	}

	unreference_key(&st->st_peer_pubkey);
	release_fragments(st);

	free_sa(st->st_sadb);
	st->st_sadb = NULL;

	if (st->st_sec_in_use) {
		SECKEYPrivateKey *privk;
		SECKEYPublicKey   *pubk;
		memcpy(&pubk, st->pubk.ptr, st->pubk.len);
		SECKEY_DestroyPublicKey(pubk);
		freeanychunk(st->pubk);
		memcpy(&privk, st->st_sec_chunk.ptr, st->st_sec_chunk.len);
		SECKEY_DestroyPrivateKey(privk);
		pfreeany(st->st_sec_chunk.ptr);
	}

	freeanychunk(st->st_firstpacket_me);
	freeanychunk(st->st_firstpacket_him);
	freeanychunk(st->st_tpacket);
	freeanychunk(st->st_rpacket);
	freeanychunk(st->st_p1isa);
	freeanychunk(st->st_gi);
	freeanychunk(st->st_gr);
	freeanychunk(st->st_shared);
	freeanychunk(st->st_ni);
	freeanychunk(st->st_nr);
	free_lsw_nss_symkey(st->st_skeyid);
	free_lsw_nss_symkey(st->st_skey_d);
	free_lsw_nss_symkey(st->st_skey_ai);
	free_lsw_nss_symkey(st->st_skey_ar);
	free_lsw_nss_symkey(st->st_skey_ei);
	free_lsw_nss_symkey(st->st_skey_er);
	free_lsw_nss_symkey(st->st_skey_pi);
	free_lsw_nss_symkey(st->st_skey_pr);
	free_lsw_nss_symkey(st->st_enc_key);

	if (st->st_ah.our_keymat != NULL)
		memset(st->st_ah.our_keymat, 0, st->st_ah.keymat_len);

	if (st->st_ah.peer_keymat != NULL)
		memset(st->st_ah.peer_keymat, 0, st->st_ah.keymat_len);

	if (st->st_esp.our_keymat != NULL)
		memset(st->st_esp.our_keymat, 0, st->st_esp.keymat_len);

	if (st->st_esp.peer_keymat != NULL)
		memset(st->st_esp.peer_keymat, 0, st->st_esp.keymat_len);

	freeanychunk(st->st_skeyid);
	freeanychunk(st->st_skey_d);
	freeanychunk(st->st_skey_ai);
	freeanychunk(st->st_skey_ar);
	freeanychunk(st->st_skey_ei);
	freeanychunk(st->st_skey_er);
	freeanychunk(st->st_skey_pi);
	freeanychunk(st->st_skey_pr);
	freeanychunk(st->st_enc_key);
	pfreeany(st->st_ah.our_keymat);
	pfreeany(st->st_ah.peer_keymat);
	pfreeany(st->st_esp.our_keymat);
	pfreeany(st->st_esp.peer_keymat);
	freeanychunk(st->st_xauth_password);
#ifdef HAVE_LABELED_IPSEC
	pfreeany(st->sec_ctx);
#endif
	pfree(st);
}

void send_v2_notification(struct state *p1st, u_int16_t type, /* <=== send_v2_notification */ 
			  struct state *encst,
			  u_char *icookie,
			  u_char *rcookie,
			  chunk_t *n_data)
{
	u_char buffer[1024];
	pb_stream reply;
	pb_stream rbody;
	chunk_t child_spi, notify_data;

	/* this function is not generic enough yet just enough for 6msg
	 * TBD accept HDR FLAGS as arg. default ISAKMP_FLAGS_R
	 * TBD when there is a child SA use that SPI in the notify paylod.
	 * TBD support encrypted notifications payloads.
	 * TBD accept Critical bit as an argument. default is set.
	 * TBD accept exchange type as an arg, default is ISAKMP_v2_SA_INIT
	 * do we need to send a notify with empty data?
	 * do we need to support more Protocol ID? more than PROTO_ISAKMP
	 */

	libreswan_log("sending %s notification %s to %s:%u",
		      encst ? "encrypted " : "",
		      enum_name(&ikev2_notify_names, type),
		      ip_str(&p1st->st_remoteaddr),
		      p1st->st_remoteport);
#if 0
/* Empty notification data section should be fine? */
	if (n_data == NULL) {
		DBG(DBG_CONTROLMORE,
		    DBG_log("don't send packet when notification data empty"));
		return;
	}
#endif

	memset(buffer, 0, sizeof(buffer));
	init_pbs(&reply, buffer, sizeof(buffer), "notification msg");

	/* HDR out */
	{
		struct isakmp_hdr n_hdr;
		zero(&n_hdr);                           /* default to 0 */  /* AAA should we copy from MD? */
		/* Impair function will raise major/minor by 1 for testing */
		n_hdr.isa_version = build_ike_version();
		memcpy(n_hdr.isa_rcookie, rcookie, COOKIE_SIZE);
		memcpy(n_hdr.isa_icookie, icookie, COOKIE_SIZE);
		n_hdr.isa_xchg = ISAKMP_v2_SA_INIT;
		n_hdr.isa_np = ISAKMP_NEXT_v2N;
		n_hdr.isa_flags &= ~ISAKMP_FLAGS_I;
		n_hdr.isa_flags  |=  ISAKMP_FLAGS_R;
#warning check msgid code here
		/* PAUL: shouldn't we set n_hdr.isa_msgid = [htonl](p1st->st_msgid); */
		if (!out_struct(&n_hdr, &isakmp_hdr_desc, &reply, &rbody)) {
			libreswan_log(
				"error initializing hdr for notify message");
			return;
		}

	}
	child_spi.ptr = NULL;
	child_spi.len = 0;

	/* build and add v2N payload to the packet */
	memset(&child_spi, 0, sizeof(child_spi));
	memset(&notify_data, 0, sizeof(notify_data));
	ship_v2N(ISAKMP_NEXT_v2NONE, DBGP(
			 IMPAIR_SEND_BOGUS_ISAKMP_FLAG) ?
		 (ISAKMP_PAYLOAD_NONCRITICAL | ISAKMP_PAYLOAD_LIBRESWAN_BOGUS) :
		 ISAKMP_PAYLOAD_NONCRITICAL, PROTO_ISAKMP,
		 &child_spi,
		 type, n_data, &rbody);

	close_message(&rbody, p1st);
	close_output_pbs(&reply);

	clonetochunk(p1st->st_tpacket, reply.start, pbs_offset(&reply),
		     "notification packet");

	send_ike_msg(p1st, __FUNCTION__);
}

static void peerlog(const char *prefix, const char *m) /* <=== peerlog */ 
{
	if (cur_connection == NULL) {
		/* we can not log it in this case. Oh well. */
		return;
	}

	if (cur_connection->log_file == NULL)
		open_peerlog(cur_connection);

	/* despite our attempts above, we may not be able to open the file. */
	if (cur_connection->log_file != NULL) {
		char datebuf[32];
		time_t n;
		struct tm tm1, *t;

		time(&n);
		t = localtime_r(&n, &tm1);

		strftime(datebuf, sizeof(datebuf), "%Y-%m-%d %T", t);
		fprintf(cur_connection->log_file, "%s %s%s\n", datebuf, prefix,
			m);

		/* now move it to the front of the list */
		CIRCLEQ_REMOVE(&perpeer_list, cur_connection, log_link);
		CIRCLEQ_INSERT_HEAD(&perpeer_list, cur_connection, log_link);
	}
}

void init_pbs(pb_stream *pbs, u_int8_t *start, size_t len, const char *name) /* <=== init_pbs */ 
{
	pbs->container = NULL;
	pbs->desc = NULL;
	pbs->name = name;
	pbs->start = pbs->cur = start;
	pbs->roof = start + len;
	pbs->lenfld = NULL;
	pbs->lenfld_desc = NULL;
}

bool subnetinsubnet(a, b) /* <=== subnetinsubnet */ 
const ip_subnet * a;
const ip_subnet *b;
{
	if (subnettypeof(a) != subnettypeof(b))
		return 0;

	if (a->maskbits < b->maskbits)  /* a is bigger than b */
		return 0;

	if (!samenbits(&a->addr, &b->addr, b->maskbits))
		return 0;

	return 1;
}

static size_t                   /* size of text, including NUL */ /* <=== reverse4 */ 
reverse4(srcp, srclen, buf, dstp)
const unsigned char *srcp;
size_t srclen;
char *buf;                      /* guaranteed large enough */
char **dstp;                    /* where to put result pointer */
{
	int i;
	char *p;

	if (srclen != IP4BYTES) /* "can't happen" */
		return 0;

	p = buf;
	for (i = IP4BYTES - 1; i >= 0; i--) {
		p += ultot(srcp[i], 10, p, PERBYTE);
		*(p - 1) = '.';   /* overwrites the NUL */
	}
	strcpy(p, "IN-ADDR.ARPA.");
	*dstp = buf;
	return strlen(buf) + 1;
}

int libreswan_DBG_log(const char *message, ...) /* <=== libreswan_DBG_log */ 
{
	va_list args;
	char m[LOG_WIDTH]; /* longer messages will be truncated */

	va_start(args, message);
	vsnprintf(m, sizeof(m), message, args);
	va_end(args);

	/* then sanitize anything else that is left. */
	(void)sanitize_string(m, sizeof(m));

	if (log_to_stderr)
		fprintf(stderr, "| %s\n", m);
	if (log_to_syslog)
		syslog(LOG_DEBUG, "| %s", m);

	return 0;
}

void close_output_pbs(pb_stream *pbs) /* <=== close_output_pbs */ 
{
	if (pbs->lenfld != NULL) {
		u_int32_t len = pbs_offset(pbs);
		int i = pbs->lenfld_desc->size;

		if (pbs->lenfld_desc->field_type == ft_lv)
			len -= sizeof(struct isakmp_attribute);
		DBG(DBG_EMITTING, DBG_log("emitting length of %s: %lu",
					  pbs->name, (unsigned long) len));
		while (i-- != 0) {
			pbs->lenfld[i] = (u_int8_t)len;
			len >>= BITS_PER_BYTE;
		}
	}
	if (pbs->container != NULL)
		pbs->container->cur = pbs->cur; /* pass space utilization up */
}

