void event_schedule(enum event_type type, time_t tm, struct state *st) /* <=== event_schedule */ 
{
	struct event *ev = alloc_thing(struct event,
				       "struct event in event_schedule()");

	passert(tm >= 0);
	ev->ev_type = type;
	ev->ev_time = tm + now();
	ev->ev_state = st;

	/* If the event is associated with a state, put a backpointer to the
	 * event in the state object, so we can find and delete the event
	 * if we need to (for example, if we receive a reply).
	 */
	if (st != NULL) {
		if (type == EVENT_DPD || type == EVENT_DPD_TIMEOUT) {
			passert(st->st_dpd_event == NULL);
			st->st_dpd_event = ev;
		} else if (type == EVENT_v2_LIVENESS) {
			passert(st->st_liveness_event == NULL);
			st->st_liveness_event = ev;
		} else {
			passert(st->st_event == NULL);
			st->st_event = ev;
		}
	}

	DBG(DBG_CONTROL, {
		    if (st == NULL) {
			    DBG_log(
				    "inserting event %s, timeout in %lu seconds",
				    enum_show(&timer_event_names,
					      type), (unsigned long)tm);
		    } else {
			    DBG_log(
				    "inserting event %s, timeout in %lu seconds for #%lu",
				    enum_show(&timer_event_names,
					      type), (unsigned long)tm,
				    ev->ev_state->st_serialno);
		    }
	    });

	if (evlist == NULL || evlist->ev_time >= ev->ev_time) {
		DBG(DBG_CONTROLMORE, DBG_log("event added at head of queue"));
		ev->ev_next = evlist;
		evlist = ev;
	} else {
		struct event *evt;

		for (evt = evlist; evt->ev_next != NULL; evt = evt->ev_next)
			if (evt->ev_next->ev_time >= ev->ev_time)
				break;

		DBG(DBG_CONTROLMORE, {
			    if (evt->ev_state == NULL) {
				    DBG_log("event added after event %s",
					    enum_show(&timer_event_names,
						      evt->ev_type));
			    } else {
				    DBG_log(
					    "event added after event %s for #%lu",
					    enum_show(&timer_event_names,
						      evt->ev_type),
					    evt->ev_state->st_serialno);
			    }
		    });

		ev->ev_next = evt->ev_next;
		evt->ev_next = ev;
	}
}

static bool samenbits(a, b, nbits) /* <=== samenbits */ 
const ip_address * a;
const ip_address *b;
int nbits;
{
	unsigned char *ap;
	unsigned char *bp;
	size_t n;
	int m;

	if (addrtypeof(a) != addrtypeof(b))
		return 0;       /* arbitrary */

	n = addrbytesptr(a, &ap);
	if (n == 0)
		return 0;       /* arbitrary */

	(void) addrbytesptr(b, &bp);
	if (nbits > (int)n * 8)
		return 0;       /* "can't happen" */

	for (; nbits >= 8 && *ap == *bp; nbits -= 8, ap++, bp++)
		continue;
	if (nbits >= 8)
		return 0;

	if (nbits > 0) {        /* partial byte */
		m = ~(0xff >> nbits);
		if ((*ap & m) != (*bp & m))
			return 0;
	}
	return 1;
}

static bool justship_v2KE(struct state *st UNUSED, /* <=== justship_v2KE */ 
			  chunk_t *g, unsigned int oakley_group,
			  pb_stream *outs, u_int8_t np)
{
	struct ikev2_ke v2ke;
	pb_stream kepbs;

	memset(&v2ke, 0, sizeof(v2ke));
	v2ke.isak_np      = np;
	v2ke.isak_group   = oakley_group;
	if (!out_struct(&v2ke, &ikev2_ke_desc, outs, &kepbs))
		return FALSE;

	if (!out_chunk(*g, &kepbs, "ikev2 g^x"))
		return FALSE;

	close_output_pbs(&kepbs);
	return TRUE;
}

void for_each_state(void *(f)(struct state *, void *data), void *data) /* <=== for_each_state */ 
{
	struct state *st, *ocs = cur_state;
	int i;

	for (i = 0; i < STATE_TABLE_SIZE; i++) {
		for (st = statetable[i]; st != NULL;
		     st = st->st_hashchain_next) {
			set_cur_state(st);
			f(st, data);
		}
	}
	cur_state = ocs;
}

bool out_struct(const void *struct_ptr, struct_desc *sd, /* <=== out_struct */ 
		pb_stream *outs, pb_stream *obj_pbs)
{
	err_t ugh = NULL;
	const u_int8_t *inp = struct_ptr;
	u_int8_t *cur = outs->cur;

	DBG(DBG_EMITTING,
	    DBG_prefix_print_struct(outs, "emit ", struct_ptr, sd, obj_pbs ==
				    NULL));

	if (outs->roof - cur < (ptrdiff_t)sd->size) {
		ugh = builddiag(
			"not enough room left in output packet to place %s",
			sd->name);
	} else {
		bool immediate = FALSE;
		pb_stream obj;
		field_desc *fp;

		obj.lenfld = NULL; /* until a length field is discovered */
		obj.lenfld_desc = NULL;

		for (fp = sd->fields; ugh == NULL; fp++) {
			size_t i = fp->size;

			/* make sure that there is space for the next structure element */
			passert(outs->roof - cur >= (ptrdiff_t)i);

			/* verify that the spot is correct in the offset */
			passert(cur - outs->cur <= (ptrdiff_t)(sd->size - i));

			/* verify that we are at the right place in the input structure */
			passert(inp - (cur - outs->cur) == struct_ptr);

#if 0
			DBG_log("out_struct: %d %s",
				(int) (cur - outs->cur),
				fp->name == NULL ? "<end>" : fp->name);
#endif
			switch (fp->field_type) {
			case ft_zig: /* should be zero, so ensure it is */
				inp += i;
				for (; i != 0; i--)
					*cur++ = '\0';
				break;
			case ft_nat:            /* natural number (may be 0) */
			case ft_len:            /* length of this struct and any following crud */
			case ft_lv:             /* length/value field of attribute */
			case ft_enum:           /* value from an enumeration */
			case ft_loose_enum:     /* value from an enumeration with only some names known */
			case ft_af_enum:        /* Attribute Format + value from an enumeration */
			case ft_af_loose_enum:  /* Attribute Format + value from an enumeration */
			case ft_set:            /* bits representing set */
			{
				u_int32_t n = 0;

				switch (i) {
				case 8 / BITS_PER_BYTE:
					n = *(const u_int8_t *)inp;
					break;
				case 16 / BITS_PER_BYTE:
					n = *(const u_int16_t *)inp;
					break;
				case 32 / BITS_PER_BYTE:
					n = *(const u_int32_t *)inp;
					break;
				default:
					bad_case(i);
				}

				switch (fp->field_type) {
				case ft_len:                            /* length of this struct and any following crud */
				case ft_lv:                             /* length/value field of attribute */
					if (immediate)
						break;                  /* not a length */
					/* We can't check the length because it will likely
					 * be filled in after variable part is supplied.
					 * We do record where this is so that it can be
					 * filled in by a subsequent close_output_pbs().
					 */
					passert(obj.lenfld == NULL);    /* only one ft_len allowed */
					obj.lenfld = cur;
					obj.lenfld_desc = fp;
					break;
				case ft_af_loose_enum: /* Attribute Format + value from an enumeration */
					if ((n & ISAKMP_ATTR_AF_MASK) ==
					    ISAKMP_ATTR_AF_TV)
						immediate = TRUE;
					break;

				case ft_af_enum: /* Attribute Format + value from an enumeration */
					if ((n & ISAKMP_ATTR_AF_MASK) ==
					    ISAKMP_ATTR_AF_TV)
						immediate = TRUE;
				/* FALL THROUGH */
				case ft_enum:   /* value from an enumeration */
					if (enum_name(fp->desc, n) == NULL) {
						ugh = builddiag(
							"%s of %s has an unknown value: %lu",
							fp->name, sd->name,
							(unsigned long)n);
					}
				/* FALL THROUGH */
				case ft_loose_enum:     /* value from an enumeration with only some names known */
					break;
				case ft_set:            /* bits representing set */
					if (!testset(fp->desc, n)) {
						ugh = builddiag(
							"bitset %s of %s has unknown member(s): %s",
							fp->name, sd->name,
							bitnamesof(fp->desc,
								   n));
					}
					break;
				default:
					break;
				}

				while (i-- != 0) {
					cur[i] = (u_int8_t)n;
					n >>= BITS_PER_BYTE;
				}
				inp += fp->size;
				cur += fp->size;
				break;
			}
			case ft_raw: /* bytes to be left in network-order */
				for (; i != 0; i--)
					*cur++ = *inp++;
				break;
			case ft_end: /* end of field list */
				passert(cur == outs->cur + sd->size);

				obj.container = outs;
				obj.desc = sd;
				obj.name = sd->name;
				obj.start = outs->cur;
				obj.cur = cur;
				obj.roof = outs->roof; /* limit of possible */
				/* obj.lenfld and obj.lenfld_desc already set */

				if (obj_pbs == NULL) {
					close_output_pbs(&obj); /* fill in length field, if any */
				} else {
					/* We set outs->cur to outs->roof so that
					 * any attempt to output something into outs
					 * before obj is closed will trigger an error.
					 */
					outs->cur = outs->roof;

					*obj_pbs = obj;
				}
				return TRUE;

			default:
				bad_case(fp->field_type);
			}
		}
	}

	/* some failure got us here: report it */
	loglog(RC_LOG_SERIOUS, "%s", ugh); /* ??? serious, but errno not relevant */
	return FALSE;
}

void loglog(int mess_no, const char *message, ...) /* <=== libreswan_loglog */ 
{
	va_list args;
	char m[LOG_WIDTH]; /* longer messages will be truncated */

	pthread_mutex_lock(&log_mutex);
	va_start(args, message);
	fmt_log(m, sizeof(m), message, args);
	va_end(args);

	log_did_something = TRUE;

	if (log_to_stderr || (log_to_file  && pluto_log_fd)) {
		if (log_with_timestamp) {
			struct tm tm1, *timeinfo;
			char fmt[32];
			time_t rtime;
			time(&rtime);
			timeinfo = localtime_r(&rtime, &tm1);
			strftime(fmt, sizeof(fmt), "%b %e %T", timeinfo);
			fprintf(log_to_stderr ? stderr : pluto_log_fd,
				"%s: %s\n", fmt, m);
		} else {
			fprintf(log_to_stderr ? stderr : pluto_log_fd, "%s\n",
				m);
		}
	}
	if (log_to_syslog)
		syslog(LOG_WARNING, "%s", m);
	if (log_to_perpeer)
		peerlog("", m);

	pthread_mutex_unlock(&log_mutex);
	whack_log(mess_no, "~%s", m);
}

