char *fmt_conn_instance(const struct connection *c, char buf[CONN_INST_BUF]) /* <=== fmt_conn_instance */ 
{
	char *p = buf;

	*p = '\0';

	if (c->kind == CK_INSTANCE) {
		if (c->instance_serial != 0) {
			snprintf(p, CONN_INST_BUF, "[%lu]",
				c->instance_serial);
			p += strlen(p);
		}

		if (c->policy & POLICY_OPPO) {
			size_t w = fmt_client(&c->spd.this.client,
					&c->spd.this.host_addr, " ", p);

			p += w;

			strcpy(p, w == 0 ? " ..." : "=== ...");
			p += strlen(p);

			addrtot(&c->spd.that.host_addr, 0, p, ADDRTOT_BUF);
			p += strlen(p);

			(void) fmt_client(&c->spd.that.client,
					&c->spd.that.host_addr, "===", p);
		} else {
			*p++ = ' ';
			addrtot(&c->spd.that.host_addr, 0, p, ADDRTOT_BUF);
		}
	}

	return buf;
}

bool addrinsubnet(a, s) /* <=== addrinsubnet */ 
const ip_address * a;
const ip_subnet *s;
{
	if (addrtypeof(a) != subnettypeof(s))
		return 0;

	if (!samenbits(a, &s->addr, s->maskbits))
		return 0;

	return 1;
}

void send_v2_notification_from_md(struct msg_digest *md UNUSED, u_int16_t type, /* <=== send_v2_notification_from_md */ 
				  chunk_t *data)
{
	struct state st;
	struct connection cnx;

	/**
	 * Create a dummy state to be able to use send_ike_msg in
	 * send_notification
	 *
	 * we need to set:
	 *   st_connection->that.host_addr
	 *   st_connection->that.host_port
	 *   st_connection->interface
	 */
	passert(md);

	memset(&st, 0, sizeof(st));
	memset(&cnx, 0, sizeof(cnx));
	st.st_connection = &cnx;
	st.st_remoteaddr = md->sender;
	st.st_remoteport = md->sender_port;
	st.st_localaddr  = md->iface->ip_addr;
	st.st_localport  = md->iface->port;
	cnx.interface = md->iface;
	st.st_interface = md->iface;

	send_v2_notification(&st, type, NULL,
			     md->hdr.isa_icookie, md->hdr.isa_rcookie, data);
}

static bool teardown_half_ipsec_sa(struct state *st, bool inbound) /* <=== teardown_half_ipsec_sa */ 
{
	/* We need to delete AH, ESP, and IP in IP SPIs.
	 * But if there is more than one, they have been grouped
	 * so deleting any one will do.  So we just delete the
	 * first one found.  It may or may not be the only one.
	 */
	struct connection *c = st->st_connection;

	struct {
		unsigned proto;
		struct ipsec_proto_info *info;
	} protos[4];
	int i;
	bool result;

	i = 0;
	if (kernel_ops->inbound_eroute && inbound &&
	    c->spd.eroute_owner == SOS_NOBODY) {
		(void) raw_eroute(&c->spd.that.host_addr, &c->spd.that.client,
				  &c->spd.this.host_addr, &c->spd.this.client,
				  256,
				  c->encapsulation == ENCAPSULATION_MODE_TRANSPORT ? SA_ESP : IPSEC_PROTO_ANY,
				  c->spd.this.protocol,
				  c->encapsulation == ENCAPSULATION_MODE_TRANSPORT ? ET_ESP : ET_UNSPEC,
				  null_proto_info, 0, c->sa_priority, 
				  ERO_DEL_INBOUND, "delete inbound"
#ifdef HAVE_LABELED_IPSEC
				  , c->policy_label
#endif
				  );
	}

	if (!kernel_ops->grp_sa) {
		if (st->st_ah.present) {
			protos[i].info = &st->st_ah;
			protos[i].proto = SA_AH;
			i++;
		}

		if (st->st_esp.present) {
			protos[i].info = &st->st_esp;
			protos[i].proto = SA_ESP;
			i++;
		}

		if (st->st_ipcomp.present) {
			protos[i].info = &st->st_ipcomp;
			protos[i].proto = SA_COMP;
			i++;
		}
	} else if (st->st_ah.present) {
		protos[i].info = &st->st_ah;
		protos[i].proto = SA_AH;
		i++;
	} else if (st->st_esp.present) {
		protos[i].info = &st->st_esp;
		protos[i].proto = SA_ESP;
		i++;
	} else {
		return TRUE;
	}
	protos[i].proto = 0;

	result = TRUE;
	for (i = 0; protos[i].proto; i++) {
		unsigned proto = protos[i].proto;
		ipsec_spi_t spi;
		const ip_address *src, *dst;

		if (inbound) {
			spi = protos[i].info->our_spi;
			src = &c->spd.that.host_addr;
			dst = &c->spd.this.host_addr;
		} else {
			spi = protos[i].info->attrs.spi;
			src = &c->spd.this.host_addr;
			dst = &c->spd.that.host_addr;
		}

		result &= del_spi(spi, proto, src, dst);
	}
	return result;
}

void send_delete(struct state *st) /* <=== send_delete */ 
{
	if (st->st_ikev2)
		ikev2_delete_out(st);
	else
		ikev1_delete_out(st);
}

const struct oakley_group_desc *lookup_group(u_int16_t group) /* <=== lookup_group */ 
{
	int i;

	for (i = 0; i != elemsof(oakley_group); i++)
		if (group == oakley_group[i].group)
			return &oakley_group[i];

	return NULL;
}

static void init_crypto_helper(struct pluto_crypto_worker *w, int n) /* <=== init_crypto_helper */ 
{
	int fds[2];

	/* reset this */
	w->pcw_pid = -1;

	if (socketpair(PF_UNIX, SOCK_STREAM, 0, fds) != 0) {
		loglog(RC_LOG_SERIOUS,
		       "could not create socketpair for helpers: %s",
		       strerror(errno));
		return;
	}

	w->pcw_helpernum = n;
	w->pcw_pipe = fds[0];
	w->pcw_helper_pipe = fds[1];
	w->pcw_maxbasicwork  = 2;
	w->pcw_maxcritwork   = 4;
	w->pcw_work     = 0;
	w->pcw_reaped = FALSE;
	w->pcw_dead   = FALSE;
	TAILQ_INIT(&w->pcw_active);

	/* set the send/received queue length to be at least maxcritwork
	 * times sizeof(pluto_crypto_req) in size
	 */
	{
		int qlen = w->pcw_maxcritwork *
			   sizeof(struct pluto_crypto_req) + 10;

		if (setsockopt(fds[0], SOL_SOCKET, SO_SNDBUF, &qlen,
			       sizeof(qlen)) == -1 ||
		    setsockopt(fds[0], SOL_SOCKET, SO_SNDBUF, &qlen,
			       sizeof(qlen)) == -1 ||
		    setsockopt(fds[1], SOL_SOCKET, SO_RCVBUF, &qlen,
			       sizeof(qlen)) == -1 ||
		    setsockopt(fds[1], SOL_SOCKET, SO_RCVBUF, &qlen,
			       sizeof(qlen)) == -1) {
			loglog(RC_LOG_SERIOUS,
			       "could not set socket queue to %d", qlen);
			return;
		}
	}

	/* set local so that child inheirits it */
	pc_helper_num = n;

	int thread_status;

	thread_status = pthread_create((pthread_t*)&w->pcw_pid, NULL,
				       pluto_helper_thread, (void*)w);
	if (thread_status != 0) {
		loglog(RC_LOG_SERIOUS, "failed to start child, error = %d",
		       thread_status);
		w->pcw_pid = -1;
		close(fds[1]);
		close(fds[0]);
		w->pcw_dead   = TRUE;
		return;
	} else {
		libreswan_log("started helper (thread) pid=%ld (fd:%d)",
			      w->pcw_pid,  w->pcw_pipe);
	}
}

void libreswan_DBG_dump(const char *label, const void *p, size_t len) /* <=== libreswan_DBG_dump */ 
{
#   define DUMP_LABEL_WIDTH 20  /* arbitrary modest boundary */
#   define DUMP_WIDTH   (4 * (1 + 4 * 3) + 1)
	char buf[DUMP_LABEL_WIDTH + DUMP_WIDTH];
	char *bp;
	const unsigned char *cp = p;

	bp = buf;

	if (label != NULL && label[0] != '\0') {
		/*
		 * Handle the label.
		 * Care must be taken to avoid buffer overrun.
		 */
		size_t llen = strlen(label);

		if (llen + 1 > sizeof(buf)) {
			DBG_log("%s", label);
		} else {
			strcpy(buf, label);
			if (buf[llen - 1] == '\n') {
				buf[llen - 1] = '\0'; /* get rid of newline */
				DBG_log("%s", buf);
			} else if (llen < DUMP_LABEL_WIDTH) {
				bp = buf + llen;
			} else {
				DBG_log("%s", buf);
			}
		}
	}

	do {
		int i, j;

		for (i = 0; len != 0 && i != 4; i++) {
			*bp++ = ' ';
			for (j = 0; len != 0 && j != 4; len--, j++) {
				static const char hexdig[] =
					"0123456789abcdef";

				*bp++ = ' ';
				*bp++ = hexdig[(*cp >> 4) & 0xF];
				*bp++ = hexdig[*cp & 0xF];
				cp++;
			}
		}
		*bp = '\0';
		DBG_log("%s", buf);
		bp = buf;
	} while (len != 0);
#   undef DUMP_LABEL_WIDTH
#   undef DUMP_WIDTH
}

